]$settings$::jsonb) item;
DO $$ BEGIN
  IF (SELECT count(*) FROM fade_settings)<>20 OR (SELECT count(DISTINCT id) FROM fade_settings)<>20
    OR (SELECT count(*) FROM fade_settings WHERE old_config<>'null'::jsonb)<>11
    THEN RAISE EXCEPTION 'Text Fading payload incomplete'; END IF;
  IF (SELECT count(*) FROM speed_reading.exercise_types WHERE name='TextFading' AND is_active AND NOT is_deleted)<>1
    THEN RAISE EXCEPTION 'Active Text Fading type missing or ambiguous'; END IF;
  IF EXISTS(SELECT 1 FROM fade_settings s LEFT JOIN speed_reading.exercises e ON e.id=s.id
    LEFT JOIN speed_reading.exercise_types t ON t.id=e.exercise_type_id
    WHERE (s.old_config<>'null'::jsonb AND e.id IS NULL) OR (e.id IS NOT NULL AND
      (t.name IS DISTINCT FROM 'TextFading' OR e.target_age_group_id IS DISTINCT FROM s.age_id
       OR e.difficulty_level<>s.level OR NOT e.is_active OR e.is_deleted
       OR (e.configuration_json IS DISTINCT FROM s.config AND e.configuration_json IS DISTINCT FROM s.old_config)
       OR (e.title IS DISTINCT FROM s.title AND e.title IS DISTINCT FROM s.old_title))))
    THEN RAISE EXCEPTION 'Text Fading baseline changed; review before applying'; END IF;
  IF EXISTS(SELECT 1 FROM speed_reading.exercises e JOIN speed_reading.exercise_types t ON t.id=e.exercise_type_id
    WHERE t.name='TextFading' AND e.is_active AND NOT e.is_deleted
      AND e.target_age_group_id IN (SELECT age_id FROM fade_settings)
      AND NOT EXISTS(SELECT 1 FROM fade_settings s WHERE s.id=e.id))
    THEN RAISE EXCEPTION 'Unexpected age-specific Text Fading entry'; END IF;
  IF EXISTS(SELECT 1 FROM fade_settings s WHERE NOT EXISTS(
    SELECT 1 FROM speed_reading.reading_texts t WHERE t.is_active AND NOT t.is_deleted AND btrim(t.content)<>''
      AND t.difficulty_level=s.level AND (t.target_age_group_id IS NULL OR t.target_age_group_id=s.age_id)
      AND (t.exercise_id IS NULL OR t.exercise_id=s.id)
      AND (SELECT count(*) FROM speed_reading.reading_questions q WHERE q.reading_text_id=t.id AND NOT q.is_deleted
        AND q.type BETWEEN 1 AND 3 AND q.bloom_level BETWEEN 1 AND 6
        AND upper(btrim(q.correct_answer)) IN ('A','B','C','D')
        AND btrim(q.option_a)<>'' AND btrim(q.option_b)<>'' AND btrim(q.option_c)<>'' AND btrim(q.option_d)<>'')>=4))
    THEN RAISE EXCEPTION 'Text Fading needs a real text with four valid questions for every age/level'; END IF;
END $$;
INSERT INTO speed_reading.exercises(id,exercise_type_id,title,description,type_code,difficulty_level,
  configuration_json,target_age_group_id,creator_id,is_active,created_at,created_by,version,is_deleted)
SELECT s.id,t.id,s.title,'Sabit gösterim temposunda kaybolan metin; ardından metne bağlı dört anlama sorusu.',
  'reading',s.level,s.config,s.age_id,seed.creator_id,true,now(),'text-fading-v1',1,false
FROM fade_settings s CROSS JOIN speed_reading.exercise_types t
CROSS JOIN LATERAL (SELECT e.creator_id FROM speed_reading.exercises e
  WHERE e.exercise_type_id=t.id AND e.target_age_group_id=s.age_id AND e.is_active AND NOT e.is_deleted
  ORDER BY e.difficulty_level,e.id LIMIT 1) seed
WHERE t.name='TextFading' AND s.old_config='null'::jsonb
ON CONFLICT(id) DO NOTHING;
UPDATE speed_reading.exercises e SET configuration_json=s.config,title=s.title,
  updated_at=now(),updated_by='text-fading-v1',version=e.version+1 FROM fade_settings s
WHERE e.id=s.id AND (e.configuration_json IS DISTINCT FROM s.config OR e.title IS DISTINCT FROM s.title);
DO $$ BEGIN
  IF (SELECT count(*) FROM fade_settings s JOIN speed_reading.exercises e ON e.id=s.id
    WHERE e.configuration_json=s.config AND e.title=s.title AND e.is_active AND NOT e.is_deleted)<>20
    THEN RAISE EXCEPTION 'Text Fading final verification failed'; END IF;
END $$;
COMMIT;
